<?php
require __DIR__.'/app/bootstrap.php';require_once __DIR__.'/app/PaymentGateway.php';
$authority=(string)($_GET['Authority']??'');$status=(string)($_GET['Status']??'');$q=$pdo->prepare('SELECT * FROM payment_transactions WHERE authority=? ORDER BY id DESC LIMIT 1');$q->execute([$authority]);$tx=$q->fetch();if(!$tx){flash('error','تراکنش پرداخت پیدا نشد.');header('Location: '.site_url());exit;}$q=$pdo->prepare('SELECT * FROM orders WHERE id=?');$q->execute([$tx['order_id']]);$order=$q->fetch();if(!$order){http_response_code(404);exit('سفارش پیدا نشد.');}
if($status!=='OK'){ $pdo->prepare("UPDATE payment_transactions SET status='cancelled',updated_at=NOW() WHERE id=? AND status='created'")->execute([$tx['id']]);flash('error','پرداخت توسط کاربر لغو شد.');header('Location: '.site_url('order.php?code='.$order['public_code']));exit;}
try{$gateway=new PaymentGateway($config);$result=$gateway->verifyPayment($authority,(int)$tx['amount_rial']);$pdo->beginTransaction();$pdo->prepare("UPDATE payment_transactions SET status='verified',reference_id=?,raw_response=?,updated_at=NOW() WHERE id=? AND status='created'")->execute([$result['ref_id'],json_encode($result['raw']),$tx['id']]);$pdo->prepare("UPDATE orders SET payment_status='paid',payment_ref=?,status=IF(status='pending','processing',status) WHERE id=?")->execute([$result['ref_id'],$order['id']]);$pdo->commit();flash('success','پرداخت با موفقیت تأیید شد. شماره مرجع: '.$result['ref_id']);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$pdo->prepare("UPDATE payment_transactions SET status='verify_failed',raw_response=?,updated_at=NOW() WHERE id=?")->execute([substr($e->getMessage(),0,2000),$tx['id']]);flash('error','تأیید پرداخت کامل نشد؛ برای بررسی با پشتیبانی تماس بگیرید.');}header('Location: '.site_url('order.php?code='.$order['public_code']));exit;
